	negative := strings.HasPrefix(s, "-")
	if negative {
		s = s[1:]
	}
	for len(s) <= 4 {
		s = "0" + s
	}
	result := s[:len(s)-4] + "." + s[len(s)-4:]
	if negative {
		return "-" + result
	}
	return result
}

