 20	// TransferResponse is the canonical response body for a transfer operation.
 21	// It is stored in the idempotency record so replays return identical JSON.
 22	type TransferResponse struct {
 23		TransferID   string  `json:"transferId"`
 24		Status       string  `json:"status"`
 25		FromWalletID string  `json:"fromWalletId"`
 26		ToWalletID   string  `json:"toWalletId"`
 27		Amount       string  `json:"amount"`
 28		CreatedAt    string  `json:"createdAt"`
 29		ProcessedAt  *string `json:"processedAt"`
 30	}
