 53	// CreateWallet is a convenience method for tests and manual setup.
 54	func (s *TransferService) CreateWallet(ctx context.Context, currency string, initialBalance domain.Amount) (*domain.Wallet, error) {
 55		tx, err := s.pool.Begin(ctx)
 56		if err != nil {
 57			return nil, fmt.Errorf("begin tx: %w", err)
 58		}
 59		defer tx.Rollback(ctx) //nolint:errcheck
 60	
 61		w, err := s.wallets.Create(ctx, tx, currency, initialBalance)
 62		if err != nil {
 63			return nil, err
