 71	// Create executes the full transfer flow atomically.
 72	//
 73	// The 14-step flow (per spec):
 74	//  1. Validate request
 75	//  2. BEGIN TRANSACTION
 76	//  3. INSERT idempotency record ON CONFLICT DO NOTHING
 77	//  4. On conflict: validate hash, return stored response
 78	//  5. Lock both wallets FOR UPDATE in sorted UUID order
 79	//  6. Verify both wallets exist
 80	//  7. Check balance; on insufficiency: record FAILED transfer, COMMIT, return 422
 81	//  8. INSERT transfer (PENDING)
 82	//  9. INSERT ledger entries (DEBIT from, CREDIT to)
 83	//  10. UPDATE wallet balances
 84	//  11. UPDATE transfer → PROCESSED
 85	//  12. UPDATE idempotency record with final response
 86	//  13. COMMIT
 87	//  14. Return response
 88	func (s *TransferService) Create(ctx context.Context, req domain.CreateTransferRequest) (*CreateResult, error) {
 89		// Step 1: domain validation
 90		if err := req.Validate(); err != nil {
 91			return nil, err
 92		}
 93	
 94		requestHash, err := hashRequest(req)
 95		if err != nil {
 96			return nil, fmt.Errorf("hash request: %w", err)
 97		}
 98	
 99		// Step 2: begin transaction
100		tx, err := s.pool.Begin(ctx)
101		if err != nil {
102			return nil, fmt.Errorf("begin tx: %w", err)
103		}
104		defer tx.Rollback(ctx) //nolint:errcheck
105	
106		// Step 3 & 4: idempotency check
107		idem, inserted, err := s.idempotency.Insert(ctx, tx, req.IdempotencyKey, requestHash)
108		if err != nil {
109			return nil, fmt.Errorf("idempotency check: %w", err)
110		}
111	
112		if !inserted {
113			// Step 4: key already exists — hash mismatch is a hard conflict; no commit needed,
114			// the deferred rollback cleans up the read-only transaction.
115			if idem.RequestHash != requestHash {
116				return nil, domain.ErrIdempotencyConflict
117			}
118			// Hash matches — commit the read-only tx and replay the stored response.
119			if err := tx.Commit(ctx); err != nil {
120				return nil, fmt.Errorf("commit replay tx: %w", err)
121			}
122			var resp TransferResponse
123			if err := json.Unmarshal(idem.ResponseBody, &resp); err != nil {
124				return nil, fmt.Errorf("unmarshal stored response: %w", err)
125			}
126			return &CreateResult{
127				Response:   &resp,
128				HTTPStatus: idem.ResponseStatus,
129				IsReplay:   true,
130			}, nil
131		}
132	
133		// Step 5: lock both wallets in sorted UUID order (deadlock prevention)
134		sortedIDs := sortedUUIDs(req.FromWalletID, req.ToWalletID)
135		wallets, err := s.wallets.GetByIDsForUpdate(ctx, tx, sortedIDs)
136		if err != nil {
137			return nil, fmt.Errorf("lock wallets: %w", err)
138		}
139	
140		// Step 6: both wallets must exist
141		if len(wallets) != 2 {
142			return nil, domain.ErrWalletNotFound
143		}
144		walletByID := make(map[uuid.UUID]*domain.Wallet, 2)
145		for _, w := range wallets {
146			walletByID[w.ID] = w
147		}
148		fromWallet, fromOK := walletByID[req.FromWalletID]
149		_, toOK := walletByID[req.ToWalletID]
150		if !fromOK || !toOK {
151			return nil, domain.ErrWalletNotFound
152		}
153	
154		// Step 7: insufficient funds — still a committed business outcome
155		if !fromWallet.Balance.GTE(req.Amount) {
156			transfer := &domain.Transfer{
157				FromWalletID: req.FromWalletID,
158				ToWalletID:   req.ToWalletID,
159				Amount:       req.Amount,
160			}
161			if err := s.transfers.Create(ctx, tx, transfer); err != nil {
162				return nil, fmt.Errorf("create failed transfer: %w", err)
163			}
164			if err := s.transfers.MarkFailed(ctx, tx, transfer.ID, domain.ErrInsufficientFunds.Error()); err != nil {
165				return nil, fmt.Errorf("mark transfer failed: %w", err)
166			}
167			transfer.Status = domain.StatusFailed
168	
169			resp := buildResponse(transfer)
170			body, err := json.Marshal(resp)
171			if err != nil {
172				return nil, fmt.Errorf("marshal response: %w", err)
173			}
174			if err := s.idempotency.UpdateResponse(ctx, tx, req.IdempotencyKey, transfer.ID, http.StatusUnprocessableEntity, body); err != nil {
175				return nil, fmt.Errorf("update idempotency: %w", err)
176			}
177			if err := tx.Commit(ctx); err != nil {
178				return nil, fmt.Errorf("commit: %w", err)
179			}
180			return &CreateResult{Response: resp, HTTPStatus: http.StatusUnprocessableEntity}, nil
181		}
182	
183		// Step 8: insert transfer row with PENDING status
184		transfer := &domain.Transfer{
185			FromWalletID: req.FromWalletID,
186			ToWalletID:   req.ToWalletID,
187			Amount:       req.Amount,
188		}
189		if err := s.transfers.Create(ctx, tx, transfer); err != nil {
190			return nil, fmt.Errorf("create transfer: %w", err)
191		}
192	
193		// Step 9: double-entry ledger
194		entries := []*domain.LedgerEntry{
195			{TransferID: transfer.ID, WalletID: req.FromWalletID, EntryType: domain.EntryDebit, Amount: req.Amount},
196			{TransferID: transfer.ID, WalletID: req.ToWalletID, EntryType: domain.EntryCredit, Amount: req.Amount},
197		}
198		if err := s.ledger.CreateEntries(ctx, tx, entries); err != nil {
199			return nil, fmt.Errorf("create ledger entries: %w", err)
200		}
201	
202		// Step 10: update balances
203		newFromBalance := fromWallet.Balance.Sub(req.Amount)
204		newToBalance := walletByID[req.ToWalletID].Balance.Add(req.Amount)
205		if err := s.wallets.UpdateBalance(ctx, tx, req.FromWalletID, newFromBalance); err != nil {
206			return nil, fmt.Errorf("update from balance: %w", err)
207		}
208		if err := s.wallets.UpdateBalance(ctx, tx, req.ToWalletID, newToBalance); err != nil {
209			return nil, fmt.Errorf("update to balance: %w", err)
210		}
211	
212		// Step 11: mark PROCESSED
213		processedAt := time.Now().UTC()
214		if err := s.transfers.MarkProcessed(ctx, tx, transfer.ID, processedAt); err != nil {
215			return nil, fmt.Errorf("mark processed: %w", err)
216		}
217		transfer.Status = domain.StatusProcessed
218		transfer.ProcessedAt = &processedAt
219	
220		// Step 12: persist final response in idempotency record
221		resp := buildResponse(transfer)
222		body, err := json.Marshal(resp)
223		if err != nil {
224			return nil, fmt.Errorf("marshal response: %w", err)
225		}
226		if err := s.idempotency.UpdateResponse(ctx, tx, req.IdempotencyKey, transfer.ID, http.StatusCreated, body); err != nil {
227			return nil, fmt.Errorf("update idempotency: %w", err)
228		}
229	
230		// Step 13: commit
231		if err := tx.Commit(ctx); err != nil {
232			return nil, fmt.Errorf("commit: %w", err)
233		}
234	
235		// Step 14: return
236		return &CreateResult{Response: resp, HTTPStatus: http.StatusCreated}, nil
237	}
