239	// hashRequest computes SHA256 over the canonical JSON of the request payload
240	// (everything except the idempotency key itself).
241	func hashRequest(req domain.CreateTransferRequest) (string, error) {
242		// Use a struct with sorted keys to get a deterministic JSON encoding.
243		payload := struct {
244			Amount       string `json:"amount"`
245			FromWalletID string `json:"fromWalletId"`
246			ToWalletID   string `json:"toWalletId"`
247		}{
248			Amount:       req.Amount.String(),
249			FromWalletID: req.FromWalletID.String(),
250			ToWalletID:   req.ToWalletID.String(),
251		}
252		b, err := json.Marshal(payload)
253		if err != nil {
254			return "", err
255		}
256		sum := sha256.Sum256(b)
257		return hex.EncodeToString(sum[:]), nil
258	}
259	
260	// sortedUUIDs returns [a, b] ordered by byte value, matching Postgres ORDER BY on uuid.
261	func sortedUUIDs(a, b uuid.UUID) []uuid.UUID {
262		if bytes.Compare(a[:], b[:]) < 0 {
263			return []uuid.UUID{a, b}
264		}
265		return []uuid.UUID{b, a}
266	}
267	
268	func buildResponse(t *domain.Transfer) *TransferResponse {
269		resp := &TransferResponse{
270			TransferID:   t.ID.String(),
271			Status:       string(t.Status),
272			FromWalletID: t.FromWalletID.String(),
273			ToWalletID:   t.ToWalletID.String(),
274			Amount:       t.Amount.String(),
275			CreatedAt:    t.CreatedAt.UTC().Format(time.RFC3339Nano),
276		}
277		if t.ProcessedAt != nil {
278			s := t.ProcessedAt.UTC().Format(time.RFC3339Nano)
279			resp.ProcessedAt = &s
280		}
281		return resp
282	}

