78	// Create executes the full transfer flow atomically.
79	//
80	// The 14-step flow (per spec):
81	//  1. Validate request
82	//  2. BEGIN TRANSACTION
83	//  3. INSERT idempotency record ON CONFLICT DO NOTHING
84	//  4. On conflict: validate hash, return stored response
85	//  5. Lock both wallets FOR UPDATE in sorted UUID order
86	//  6. Verify both wallets exist
87	//  7. Check balance; on insufficiency: record FAILED transfer, COMMIT, return 422
88	//  8. INSERT transfer (PENDING)
89	//  9. INSERT ledger entries (DEBIT from, CREDIT to)
90	//  10. UPDATE wallet balances
91	//  11. UPDATE transfer → PROCESSED
92	//  12. UPDATE idempotency record with final response
93	//  13. COMMIT
94	//  14. Return response
95	func (s *TransferService) Create(ctx context.Context, req domain.CreateTransferRequest) (*CreateResult, error) {
96		// Step 1: domain validation
97		if err := req.Validate(); err != nil {
98			return nil, err
99		}
100	
101		requestHash, err := hashRequest(req)
102		if err != nil {
103			return nil, fmt.Errorf("hash request: %w", err)
104		}
105	
106		// Step 2: begin transaction
107		tx, err := s.pool.Begin(ctx)
108		if err != nil {
109			return nil, fmt.Errorf("begin tx: %w", err)
110		}
111		defer tx.Rollback(ctx) //nolint:errcheck
112	
113		// Step 3 & 4: idempotency check
114		idem, inserted, err := s.idempotency.Insert(ctx, tx, req.IdempotencyKey, requestHash)
115		if err != nil {
116			return nil, fmt.Errorf("idempotency check: %w", err)
117		}
118	
119		if !inserted {
120			// Step 4: key already exists — hash mismatch is a hard conflict; no commit needed,
121			// the deferred rollback cleans up the read-only transaction.
122			if idem.RequestHash != requestHash {
123				return nil, domain.ErrIdempotencyConflict
124			}
125			// Hash matches — commit the read-only tx and replay the stored response.
126			if err := tx.Commit(ctx); err != nil {
127				return nil, fmt.Errorf("commit replay tx: %w", err)
128			}
129			var resp TransferResponse
130			if err := json.Unmarshal(idem.ResponseBody, &resp); err != nil {
131				return nil, fmt.Errorf("unmarshal stored response: %w", err)
132			}
133			return &CreateResult{
134				Response:   &resp,
135				HTTPStatus: idem.ResponseStatus,
136				IsReplay:   true,
137			}, nil
138		}
139	
140		// Step 5: lock both wallets in sorted UUID order (deadlock prevention)
141		sortedIDs := sortedUUIDs(req.FromWalletID, req.ToWalletID)
142		wallets, err := s.wallets.GetByIDsForUpdate(ctx, tx, sortedIDs)
143		if err != nil {
144			return nil, fmt.Errorf("lock wallets: %w", err)
145		}
146	
147		// Step 6: both wallets must exist
148		if len(wallets) != 2 {
149			return nil, domain.ErrWalletNotFound
150		}
151		walletByID := make(map[uuid.UUID]*domain.Wallet, 2)
152		for _, w := range wallets {
153			walletByID[w.ID] = w
154		}
155		fromWallet, fromOK := walletByID[req.FromWalletID]
156		_, toOK := walletByID[req.ToWalletID]
157		if !fromOK || !toOK {
158			return nil, domain.ErrWalletNotFound
159		}
160	
161		// Step 7: insufficient funds — still a committed business outcome
162		if !fromWallet.Balance.GTE(req.Amount) {
163			return s.handleInsufficientFunds(ctx, tx, req)
164		}
165		return s.executeSuccessfulTransfer(ctx, tx, req, fromWallet, walletByID[req.ToWalletID])
166	}
